using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class FloodJbFix{static double next;static FloodJbFix(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+4;if(File.Exists("D:/-11-scene3-audit/flood-jb-fixed.txt")||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.name!="scene3")return;try{var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();var floor=all.Single(r=>r.name=="flood");var cups=all.Where(r=>r.name=="jb1"||r.name=="jb2").ToArray();if(cups.Length!=2)throw new Exception("Expected jb1 and jb2");var shader=Shader.Find("BlenderScene3/FloodSatinMarble");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Floor shader compile failed");EditorSceneManager.SaveScene(s);File.Copy(s.path,"D:/-11-scene3-audit/scene3.before-flood-jb.unity",true);var p="Assets/BlenderScene3/Materials/FloodSatinMarble.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(floor.sharedMaterial);AssetDatabase.CreateAsset(m,p);}else m.CopyPropertiesFromMaterial(floor.sharedMaterial);m.shader=shader;EditorUtility.SetDirty(m);Undo.RecordObject(floor,"Reduce floor glare");floor.sharedMaterials=floor.sharedMaterials.Select(x=>m).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(floor);var rows=new List<string>{"flood|shader="+m.shader.name+"|minimumRoughness=0.55|source color/normal/roughness maps preserved"};
 foreach(var r in cups){string helper=r.name+" Reflection";var go=s.GetRootGameObjects().FirstOrDefault(g=>g.name==helper);if(!go){go=new GameObject(helper);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go,s);Undo.RegisterCreatedObjectUndo(go,"Restore trophy reflection");}go.transform.position=r.bounds.center;var pr=go.GetComponent<ReflectionProbe>();if(!pr)pr=go.AddComponent<ReflectionProbe>();pr.mode=UnityEngine.Rendering.ReflectionProbeMode.Custom;pr.boxProjection=true;pr.size=r.bounds.size+new Vector3(.35f,.35f,.35f);pr.blendDistance=.05f;pr.importance=200;pr.intensity=1.25f;var cube=AssetDatabase.LoadAssetAtPath<Cubemap>("Assets/BlenderScene3/Materials/guizi1Environment.asset");if(!cube)throw new Exception("Room reflection cubemap missing");pr.customBakedTexture=cube;Undo.RecordObject(r,"Restore trophy metallic reflection");r.reflectionProbeUsage=UnityEngine.Rendering.ReflectionProbeUsage.Simple;r.probeAnchor=go.transform;PrefabUtility.RecordPrefabInstancePropertyModifications(r);foreach(var mat in r.sharedMaterials){if(!mat.HasProperty("_MainTex")||!mat.GetTexture("_MainTex")||!mat.GetTexture("_MetalTex")||!mat.GetTexture("_RoughTex")||!mat.GetTexture("_BumpMap"))throw new Exception("Trophy source PBR map missing: "+r.name);}rows.Add(r.name+"|source base/metallic/roughness/normal maps verified|localReflectionIntensity="+pr.intensity);}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllLines("D:/-11-scene3-audit/flood-jb-fixed.txt",rows);SceneView.RepaintAll();}catch(Exception e){File.WriteAllText("D:/-11-scene3-audit/flood-jb-error.txt",e.ToString());}}}

#endif
